from datetime import datetime
from contextlib import contextmanager
import logging
import paramiko
import os
import shutil
from typing import Optional, List

from taf.sbts.oam.coam.admin import admin
from taf.gnb.oam.coam.cu import cu as vcu_admin
from taf.gnb.oam.coam.vdu import Vdu as vdu_admin

from taf.rfrl.scrambling_logs_collector.resources.python.globals import LMP_IPV4, OAM_USERNAME, \
    OAM_PASSWORD, CLOUD_USERNAME, CLOUD_PASSWORD, TEAM_DOMAINS, DOMAIN_FILE_REGEXES, DATE_FORMAT

logger = logging.getLogger(__name__)


@contextmanager
def admin_connection(bts_host: str = LMP_IPV4, username: str = OAM_USERNAME, password: str = OAM_PASSWORD,
                     alias: str = 'scrambling'):
    conn = admin().connect_to(bts_host=bts_host, username=username, password=password, name=alias)
    yield conn
    admin().teardown_admin(connection=alias)


@contextmanager
def vdu_admin_conn(host: str, port: int = 443, username: str = CLOUD_USERNAME,
                   password: str = CLOUD_PASSWORD, secure: bool = True, alias: str = 'scrambling'):
    conn_vdu = vdu_admin().connect_to(host=host, port=port, username=username, password=password, secure=secure,
                                      connection_name=alias)
    yield conn_vdu
    vdu_admin().disconnect(vdu_connection=alias)


@contextmanager
def vcu_admin_conn(host: str, port: int = 443, username: str = CLOUD_USERNAME,
                   password: str = CLOUD_PASSWORD, secure: bool = True, alias: str = 'scrambling'):
    conn_vcu = vcu_admin().connect_to(host=host, port=port, username=username, password=password, secure=secure,
                                      alias=alias)
    yield conn_vcu
    vcu_admin().disconnect(connection=alias)


def get_domain(team_name: str) -> str:
    """
    Get domain of team name. Domains are predefined in proxy_script.py in Log scrambling testing framework.
    Team name is not case and white char sensitive.
    :param team_name:   Team name, i.e. PZ3WRO4
    :return:            Domain of team name, i.e. TRSSEC
    """
    team_name = "".join(team_name.split()).upper()
    return TEAM_DOMAINS.get(team_name, "")


def get_domain_regex_by_log_type(domain: str, input_log_type: str) -> Optional[str]:
    """
    Get file regexes specific for domain per log type. For example, in TRSSEC syslog and scf files which
    are collected by DCAP are named syslog.LOG, teardown_scf.xml
    :param domain:          Domain associated with team, i.e. TRSSEC
    :param input_log_type:  input log type identifier, i.e. __snapshot__
    :return:                Regex for input type of domain logs
    """
    return DOMAIN_FILE_REGEXES.get(domain, {}).get(input_log_type, None)


def get_current_time() -> str:
    return datetime.now().strftime(DATE_FORMAT)


def get_sw_version(remote_host: str) -> str:
    with admin_connection(bts_host=remote_host) as conn:
        sw_version = conn.get_sw_version()
    return sw_version


def get_sw_version_vcu(remote_host: str) -> str:
    with vcu_admin_conn(host=remote_host) as conn:
        sw_version = conn.get_active_software_version()
    return sw_version


def get_sw_version_vdu(remote_host: str) -> str:
    with vdu_admin_conn(host=remote_host) as conn:
        vdu_state_data = conn.get_vdu_state_data()
        sw_version = vdu_state_data['software_version']
    return sw_version


def sftp_connection_available(ip: str, username: str, password: str) -> bool:
    status = True
    ssh = paramiko.SSHClient()
    ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
    try:
        ssh.connect(ip, username=username, password=password)
        sftp = ssh.open_sftp()
        sftp.close()
    except Exception:
        status = False
    return status


def get_hostname() -> str:
    return os.uname()[1].replace(" ", "-")


def clear_directories(directory_paths: List[str]):
    for directory in directory_paths:
        clear_directory_contents(directory)


def clear_directory_contents(directory_path: str):
    if os.path.exists(directory_path):
        for item in os.listdir(directory_path):
            item_path = os.path.join(directory_path, item)
            if os.path.isfile(item_path):
                os.remove(item_path)
            elif os.path.isdir(item_path):
                shutil.rmtree(item_path)
        print(f"The contents of '{directory_path}' has been cleared")


def get_list_from_string(string_input: str):
    """
    Create list based on string elements separated by coma.
    :param string_input:      String separated by coma. It can contain spaces between elements, which will be removed.
                        e.g. __snapshot_vDU__,__snapshot_vCU__, __snapshot__
    :return:            List with separate elements e.g. ['__snapshot_vDU__', '__snapshot_vCU__', '__snapshot__']
    """
    if not string_input:
        return []
    items = string_input.split(',')
    list_from_string = []
    for item in items:
        item_without_spaces = item.strip()
        if item_without_spaces:
            list_from_string.append(item_without_spaces)

    return list_from_string
